<parameter name="file_path">/ErrorBoundary.tsx</parameter>
<parameter name="content">import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    this.setState({ errorInfo: info });

    console.error("[ErrorBoundary] Caught render error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);

    this.props.onError?.(error, info);
  }

  private handleRetry = (): void => {
    this.setState({ error: null, errorInfo: null });
  };

  render(): ReactNode {
    const { error, errorInfo } = this.state;
    const { children, fallback } = this.props;

    if (!error) {
      return children;
    }

    if (fallback) {
      return fallback;
    }

    return (
      <div role="alert" style={styles.container}>
        <div style={styles.card}>
          <h2 style={styles.heading}>Something went wrong</h2>
          <p style={styles.message}>{error.message}</p>
          {process.env.NODE_ENV !== "production" && errorInfo && (
            <details style={styles.details}>
              <summary style={styles.summary}>Stack trace</summary>
              <pre style={styles.stack}>
                {error.stack}
                {"\n\nComponent stack:"}
                {errorInfo.componentStack}
              </pre>
            </details>
          )}
          <button onClick={this.handleRetry} style={styles.button}>
            Try again
          </button>
        </div>
      </div>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "100vh",
    padding: "1rem",
    backgroundColor: "#f9fafb",
  },
  card: {
    maxWidth: "480px",
    width: "100%",
    padding: "2rem",
    backgroundColor: "#fff",
    borderRadius: "8px",
    boxShadow: "0 1px 4px rgba(0,0,0,0.12)",
    textAlign: "center" as const,
  },
  heading: {
    margin: "0 0 0.5rem",
    fontSize: "1.25rem",
    color: "#111",
  },
  message: {
    margin: "0 0 1.25rem",
    color: "#6b7280",
    wordBreak: "break-word" as const,
  },
  details: {
    marginBottom: "1.25rem",
    textAlign: "left" as const,
  },
  summary: {
    cursor: "pointer",
    color: "#6b7280",
    fontSize: "0.875rem",
  },
  stack: {
    marginTop: "0.5rem",
    padding: "0.75rem",
    backgroundColor: "#f3f4f6",
    borderRadius: "4px",
    fontSize: "0.75rem",
    overflowX: "auto" as const,
    whiteSpace: "pre-wrap" as const,
    wordBreak: "break-word" as const,
    color: "#374151",
  },
  button: {
    padding: "0.5rem 1.25rem",
    backgroundColor: "#2563eb",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    fontSize: "0.875rem",
    fontWeight: 600,
    cursor: "pointer",
  },
};
